                <span className="text-[var(--color-text-primary)] [font:var(--font-body-medium-semibold)]">
                  {h.symbol}
                </span>
                <span className="truncate text-[var(--color-text-secondary)] [font:var(--font-body-medium)]">
                  {h.name}
