  { field: 'aum', headerName: 'AUM', flex: 1, minWidth: 120, valueFormatter: (p) => currency(p.value as number) },
  { field: 'risk', headerName: 'Risk', width: 130 },
  { field: 'lastContact', headerName: 'Last Contact', width: 130 },
  {
    field: 'status',
    headerName: 'Status',
    width: 120,
